before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>

int main()
{
    int count{0};
    if ((std::cin >> count) && count >= 0)
    {
        std::cout << "Accepted: " << count << "\n";
    }
    else
    {
        std::cout << "Invalid count\n";
    }
}

```

